/** 🕹️handles wire twin, mirrors `./🦀️.rs` (generated by `wp02-gen-twins.py`). */
import type { EntityRef, Interval, LocalizedCopy, Vec3 } from "../🟦️.ts";

export interface Affine {
  base: number;
  k: number;
}

export interface FieldBinding {
  path: string;
  map: Affine;
  unit: string;
  quantise: Quantise | null;
}

export interface SnapRule {
  grid: number | null;
  increment: number | null;
  targets: number[];
  catalogue: number[];
  tolerance: number;
}

export interface Handle {
  id: string;
  entity: EntityRef;
  kind: HandleKind;
  anchor: Vec3;
  grip: GripStyle;
  writes: FieldBinding[];
  snap: SnapRule;
  limits: Interval | null;
  accessibleName: LocalizedCopy;
}

export interface HandleDrag {
  handle: string;
  s: number;
  startedSeq: number;
}

export interface ResolvedWrite {
  path: string;
  value: number;
  token: string | null;
  unit: string;
}

export interface ChoiceToken {
  token: string;
  label: LocalizedCopy;
}

export type GripStyle = "arrow" | "diamond" | "ring";

export type Quantise =
  | { kind: "round"; data: { step: number } }
  | { kind: "choice"; data: { values: number[] } }
  | { kind: "int" }
  | { kind: "decades"; data: { perDecade: number } }
  | { kind: "token"; data: { tokens: ChoiceToken[] } };

export type HandleKind =
  | { kind: "translate"; data: { axis: Vec3 } }
  | { kind: "translatePlane"; data: { normal: Vec3 } }
  | { kind: "scalarAlong"; data: { axis: Vec3 } }
  | { kind: "radial"; data: { centre: Vec3 } }
  | { kind: "angular"; data: { axis: Vec3; centre: Vec3 } }
  | { kind: "dimensionLine" }
  | { kind: "countStepper" }
  | { kind: "choiceStepper" }
  | { kind: "faceOffset"; data: { normal: Vec3 } };
